<script>document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('[data-wizard]'),steps=[...f.querySelectorAll('[data-step]')],tabs=[...f.querySelectorAll('[data-step-target]')],prev=f.querySelector('[data-prev]'),next=f.querySelector('[data-next]'),submit=f.querySelector('[data-submit]');let current=1;const show=n=>{current=n;steps.forEach(x=>x.classList.toggle('active',+x.dataset.step===n));tabs.forEach(x=>x.classList.toggle('active',+x.dataset.stepTarget===n));prev.hidden=n===1;next.hidden=n===4;submit.hidden=n!==4};next.onclick=()=>show(Math.min(4,current+1));prev.onclick=()=>show(Math.max(1,current-1));tabs.forEach(x=>x.onclick=()=>show(+x.dataset.stepTarget));show(1)});</script>
